// Current Stock report: true ledger balance per product (stock in − stock out,
// corrections applied) in the product's unit. The rows come from the
// inventory already loaded by App — the backend builds /api/inventory and
// /api/reports/current-stock with the same function — so no extra request is
// made; exports are generated by the backend.
import { useState } from "react";
import { downloadFile, getErrorMessage, todayStamp } from "../api.js";

const STATUS = {
  out: { label: "Out of stock", className: "low" },
  low: { label: "Low", className: "warn" },
  ok: { label: "OK", className: "ok" },
};

const conflictSummary = (conflicts = []) =>
  conflicts.map((c) => `${c.quantity} ${c.unit} (stock ${c.direction})`).join(", ");

export default function CurrentStockReport({ items, loaded, loading, error, onRetry }) {
  const [includeArchived, setIncludeArchived] = useState(false);
  const [exportError, setExportError] = useState("");
  const [exporting, setExporting] = useState("");

  const rows = items.filter((item) => includeArchived || item.isActive !== false);
  const counts = {
    out: rows.filter((r) => r.status === "out").length,
    low: rows.filter((r) => r.status === "low").length,
    ok: rows.filter((r) => r.status === "ok").length,
    conflicts: rows.filter((r) => r.unitConflicts?.length > 0).length,
  };

  const exportAs = async (format) => {
    const ext = format === "pdf" ? "pdf" : "xlsx";
    const filename = `current-stock${includeArchived ? "-with-archived" : ""}-${todayStamp()}.${ext}`;
    setExportError("");
    setExporting(format);
    try {
      await downloadFile(`/api/export/current-stock/${format}`, filename, {
        includeArchived: includeArchived || undefined,
      });
    } catch (err) {
      console.error(err);
      setExportError(getErrorMessage(err, `Current stock ${format === "pdf" ? "PDF" : "Excel"} export failed`));
    } finally {
      setExporting("");
    }
  };

  return (
    <section className="current-stock">
      <div className="current-stock-header">
        <h2 className="reports-section-title">Current Stock</h2>
        <div className="current-stock-actions">
          <label className="inline-check">
            <input
              type="checkbox"
              checked={includeArchived}
              onChange={(e) => setIncludeArchived(e.target.checked)}
            />
            Include archived
          </label>
          <button onClick={() => exportAs("pdf")} disabled={Boolean(exporting)}>
            {exporting === "pdf" ? "Exporting..." : "Export PDF"}
          </button>
          <button onClick={() => exportAs("excel")} disabled={Boolean(exporting)}>
            {exporting === "excel" ? "Exporting..." : "Export Excel"}
          </button>
        </div>
      </div>

      {exportError && <p className="reports-error">{exportError}</p>}
      {error && (
        <p className="reports-error">
          {error}
          {loaded && " — showing the last loaded data."}{" "}
          <button className="link-btn" onClick={onRetry} disabled={loading}>
            Retry
          </button>
        </p>
      )}

      {loaded && (
        <p className="current-stock-summary">
          {rows.length} products · <span className="status-pill low">{counts.out} out</span>{" "}
          <span className="status-pill warn">{counts.low} low</span>{" "}
          <span className="status-pill ok">{counts.ok} OK</span>
          {counts.conflicts > 0 && <span className="unit-warning-inline">⚠ {counts.conflicts} with unit conflicts</span>}
        </p>
      )}

      <div className="table-wrapper">
        {!loaded ? (
          <p className="loading-state">{loading ? "Loading current stock..." : "Current stock unavailable."}</p>
        ) : rows.length === 0 ? (
          <p className="loading-state">No products.</p>
        ) : (
          <table className="reports-table">
            <thead>
              <tr>
                <th>Product</th>
                <th>Unit</th>
                <th>Available</th>
                <th>Min Stock</th>
                <th>Status</th>
                <th>Unit conflict</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => {
                const status = STATUS[row.status] || STATUS.ok;
                return (
                  <tr key={row._id}>
                    <td data-label="Product">
                      {row.product}
                      {row.isActive === false && <span className="archived-tag">archived</span>}
                    </td>
                    <td data-label="Unit">{row.unit}</td>
                    <td data-label="Available">{row.quantity}</td>
                    <td data-label="Min Stock">
                      {row.minStock}
                      {row.minStockIsDefault && <span className="muted"> (default)</span>}
                    </td>
                    <td data-label="Status">
                      <span className={`status-pill ${status.className}`}>{status.label}</span>
                    </td>
                    <td data-label="Unit conflict">
                      {row.unitConflicts?.length > 0 ? (
                        <span className="unit-warning-inline" title="Review and correct these in the product's History">
                          ⚠ {conflictSummary(row.unitConflicts)}
                        </span>
                      ) : (
                        "—"
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </section>
  );
}
